previsioni.codice:
func double_value(amount: int) -> int:
	return amount * 2


func run() -> int:
	var score: int = 15
	var result: int = double_value(score)
	return result

var speed: float = 100.0


func boost_speed() -> void:
	var speed: float = 300.0


func run() -> float:
	boost_speed()
	return speed

func calculate_points(collected: bool) -> int:
	if collected:
		return 50
	return 10
	return 100


func run() -> int:
	var bonus: int = calculate_points(true)
	return bonus

func alter_coordinate(x: float) -> void:
	x += 40.0


func run() -> float:
	var player_x: float = 100.0
	alter_coordinate(player_x)
	return player_x
